import{_ as o,o as r,c as a,a2 as i}from"./chunks/framework.DdtnLau3.js";const k=JSON.parse('{"title":"开始使用","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/index.md","filePath":"zh/guide/index.md"}'),t={name:"zh/guide/index.md"};function n(s,e,p,d,h,l){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h1><p>Piwork 有两个入口：<strong>Core</strong> 在 Linux Docker 主机上管理 Work；<strong>CLI / Desktop</strong> 连接 Core，并在浏览器中提供操作界面。Core 还负责管理 Agent、Service 和辅助容器。</p><p>第一次使用，建议在同一台 Linux 电脑上运行 Core 和 Desktop。执行 AI 任务还需要受支持的模型服务和 API Key。</p><ol><li><a href="/piwork/zh/guide/installation.html">安装并配置 Core</a>。</li><li><a href="/piwork/zh/guide/quick-start.html">启动 Desktop、登录并创建 Work</a>。</li><li><a href="/piwork/zh/guide/first-work.html">运行、导出和导入第一个 Work</a>。</li></ol><p>已有可用的 Core？直接阅读<a href="/piwork/zh/guide/quick-start.html">快速开始</a>。</p><h2 id="第一次体验" tabindex="-1">第一次体验 <a class="header-anchor" href="#第一次体验" aria-label="Permalink to &quot;第一次体验&quot;">​</a></h2><p>创建 Work，启动它的 Harness，让它生成一个文件，再通过 Desktop 查看。停止并导出 Work，导入为一个独立副本，继续使用其中的文件和历史。</p><p>想尝试应用工作空间，可以阅读 <a href="/piwork/zh/demo/kanban.html">Kanban Work 演示说明</a>。</p><h2 id="当前支持范围" tabindex="-1">当前支持范围 <a class="header-anchor" href="#当前支持范围" aria-label="Permalink to &quot;当前支持范围&quot;">​</a></h2><p>Core 运行在一台 Linux 主机上。Docker 镜像当前面向 <code>linux/amd64</code>。CLI 容器可以在 Linux 上运行，也可以在 Windows Docker Desktop 的 Linux 容器模式下运行；浏览器与 CLI 必须在同一台电脑上。</p><p>WSL2 用户需要能访问 Docker Engine Unix socket 的 Linux 环境。当前交付记录没有单独验证 WSL2 Core；已记录的起点是 Linux 主机。</p><p>第一版官网使用已有的 <code>0.1.0</code> Docker 候选镜像集。<a href="/piwork/zh/spec/">规范概览</a>记录了核对的源码版本和实验性行为。</p>',12)])])}const u=o(t,[["render",n]]);export{k as __pageData,u as default};
